package engine

import (
	"context"
	"io"
)

// AttachmentObjectStore is a private object backend. Keys are generated by the
// engine from a workspace digest and an opaque attachment ID, never filenames.
// Open must return bounded seekable content, for example a temporary file.
type AttachmentObjectStore interface {
	Put(context.Context, string, []byte) error
	Open(context.Context, string) (io.ReadSeekCloser, error)
	Delete(context.Context, string) error
}

func attachmentObjectKey(scope, id string) string { return Digest(scope) + "/" + id }
